1	import React, { useState, useEffect, useMemo, useCallback, useRef } from 'react';
2	import { useTriggerStore } from '../../store/useTriggerStore';
3	import { ComponentFileNode, ComponentEntry } from '../../utils/componentScanner';
4	import { ComponentManager } from '../../utils/componentManager';
5	import { ConditionManager } from '../../utils/conditionManager';
6	import { OptionEditorModal } from './OptionEditorModal';
7	import { NotionConditionMultiSelect } from './NotionConditionMultiSelect';
8	import { renderComponentIcon } from '../../utils/iconResolver';
9	import { generateHexId } from '../../utils/hexId';
10	import {
11	  Table,
12	  Plus,
13	  Search,
14	  Layers,
15	  Sparkles,
16	  Lock,
17	  Unlock,
18	  Trash2,
19	  Copy,
20	  Edit3,
21	  Save,
22	  RotateCcw,
23	  Check,
24	  X,
25	  ExternalLink,
26	  Filter,
27	  CheckSquare,
28	  Hash,
29	  FileText,
30	  AlertCircle,
31	  Eye,
32	  Folder,
33	  ChevronLeft,
34	  ChevronRight,
35	  Maximize2,
36	  MoveHorizontal,
37	} from 'lucide-react';
38	
39	export const ComponentsManagerView: React.FC = () => {
40	  const { app, folders, matrixDomains, conditions, reload } = useTriggerStore();
41	
42	  // 1. Gather all folder containers
43	  const allFolderNodes = useMemo(() => {
44	    return [
45	      ...folders.map((f) => ({
46	        id: f.relPath,
47	        displayName: f.displayName,
48	        relPath: f.relPath,
49	        icon: f.meta?.icon,
50	        files: f.files,
51	        isMatrix: false,
52	      })),
53	      ...matrixDomains.map((d) => ({
54	        id: d.relPath,
55	        displayName: d.displayName,
56	        relPath: d.relPath,
57	        icon: d.meta?.icon,
58	        files: d.files,
59	        isMatrix: true,
60	      })),
61	    ];
62	  }, [folders, matrixDomains]);
63	
64	  // Selected Folder Index / ID
65	  const [selectedFolderId, setSelectedFolderId] = useState<string>(() => {
66	    return allFolderNodes[0]?.id || '';
67	  });
68	
69	  // Active Folder Node
70	  const activeFolder = useMemo(() => {
71	    return allFolderNodes.find((f) => f.id === selectedFolderId) || allFolderNodes[0] || null;
72	  }, [allFolderNodes, selectedFolderId]);
73	
74	  // Selected File RelPath in the Active Folder
75	  const [selectedFileRelPath, setSelectedFileRelPath] = useState<string>(() => {
76	    return allFolderNodes[0]?.files[0]?.relPath || '';
77	  });
78	
79	  // When active folder changes, auto-select its first file if current selectedFile is not in it
80	  useEffect(() => {
81	    if (activeFolder && activeFolder.files.length > 0) {
82	      const isFileInFolder = activeFolder.files.some((f) => f.relPath === selectedFileRelPath);
83	      if (!isFileInFolder) {
84	        setSelectedFileRelPath(activeFolder.files[0].relPath);
85	      }
86	    }
87	  }, [activeFolder, selectedFileRelPath]);
88	
89	  // Active Selected File Node
90	  const activeFileNode = useMemo<ComponentFileNode | null>(() => {
91	    for (const folder of allFolderNodes) {
92	      const match = folder.files.find((f) => f.relPath === selectedFileRelPath);
93	      if (match) return match;
94	    }
95	    return null;
96	  }, [allFolderNodes, selectedFileRelPath]);
97	
98	  // In-Memory Working Copy of the Active File's Entries (for instant in-place Notion table editing)
99	  const [workingEntries, setWorkingEntries] = useState<Record<string, ComponentEntry>>({});
100	  const [isDirty, setIsDirty] = useState(false);
101	  const [dirtyCount, setDirtyCount] = useState(0);
102	  const [isSaving, setIsSaving] = useState(false);
103	  const [saveSuccessNotice, setSaveSuccessNotice] = useState(false);
104	
105	  // Synchronize working copy when changing files or reloading
106	  useEffect(() => {
107	    if (activeFileNode) {
108	      setWorkingEntries(JSON.parse(JSON.stringify(activeFileNode.entries || {})));
109	      setIsDirty(false);
110	      setDirtyCount(0);
111	    }
112	  }, [activeFileNode?.relPath, activeFileNode?.entries]);
113	
114	  // Search & Filter state
115	  const [searchQuery, setSearchQuery] = useState('');
116	  const [filterMode, setFilterMode] = useState<'all' | 'completed' | 'draft' | 'tag_team'>('all');
117	
118	  // Deep Modal Inspector State
119	  const [isModalEditorOpen, setIsModalEditorOpen] = useState(false);
120	  const [modalKey, setModalKey] = useState<string | null>(null);
121	  const [modalEntry, setModalEntry] = useState<ComponentEntry | null>(null);
122	
123	  // --- HORIZONTAL NOTION-STYLE DRAG & WALL EDGE NAVIGATION ---
124	  const tableContainerRef = useRef<HTMLDivElement>(null);
125	  const isDraggingRef = useRef(false);
126	  const startXRef = useRef(0);
127	  const startScrollLeftRef = useRef(0);
128	  const edgeScrollAnimRef = useRef<number | null>(null);
129	
130	  const [canScrollLeft, setCanScrollLeft] = useState(false);
131	  const [canScrollRight, setCanScrollRight] = useState(false);
132	  const [scrollProgress, setScrollProgress] = useState(0);
133	
134	  // Update scroll boundaries
135	  const checkScrollBoundaries = useCallback(() => {
136	    const el = tableContainerRef.current;
137	    if (!el) return;
138	    const maxScroll = el.scrollWidth - el.clientWidth;
139	    setCanScrollLeft(el.scrollLeft > 4);
140	    setCanScrollRight(el.scrollLeft < maxScroll - 4);
141	    setScrollProgress(maxScroll > 0 ? (el.scrollLeft / maxScroll) * 100 : 0);
142	  }, []);
143	
144	  useEffect(() => {
145	    checkScrollBoundaries();
146	    window.addEventListener('resize', checkScrollBoundaries);
147	    return () => window.removeEventListener('resize', checkScrollBoundaries);
148	  }, [checkScrollBoundaries, workingEntries]);
149	
150	  // Smooth Wall Jump / Continuous Pan handlers
151	  const scrollHorizontally = useCallback((delta: number) => {
152	    if (!tableContainerRef.current) return;
153	    tableContainerRef.current.scrollBy({ left: delta, behavior: 'smooth' });
154	    setTimeout(checkScrollBoundaries, 200);
155	  }, [checkScrollBoundaries]);
156	
157	  // Mouse Drag-to-Scroll & Wall Proximity Auto-Scroll
158	  const handleMouseDown = (e: React.MouseEvent<HTMLDivElement>) => {
159	    // Only trigger drag if not clicking inside an interactive input, textarea, select, or button
160	    const target = e.target as HTMLElement;
161	    if (
162	      target.tagName === 'INPUT' ||
163	      target.tagName === 'TEXTAREA' ||
164	      target.tagName === 'SELECT' ||
165	      target.tagName === 'BUTTON' ||
166	      target.closest('button') ||
167	      target.closest('select') ||
168	      target.closest('input') ||
169	      target.closest('textarea')
170	    ) {
171	      return;
172	    }
173	
174	    if (!tableContainerRef.current) return;
175	    isDraggingRef.current = true;
176	    startXRef.current = e.clientX;
177	    startScrollLeftRef.current = tableContainerRef.current.scrollLeft;
178	  };
179	
180	  const handleMouseMove = (e: React.MouseEvent<HTMLDivElement>) => {
181	    if (!tableContainerRef.current) return;
182	    const el = tableContainerRef.current;
183	    const rect = el.getBoundingClientRect();
184	
185	    // 1. Direct Left-Click Drag Pan
186	    if (isDraggingRef.current) {
187	      const dx = e.clientX - startXRef.current;
188	      el.scrollLeft = startScrollLeftRef.current - dx;
189	      checkScrollBoundaries();
190	    }
191	
192	    // 2. Wall Proximity Auto-Scroll (Edge Detection within 60px of left/right walls)
193	    const distToRight = rect.right - e.clientX;
194	    const distToLeft = e.clientX - rect.left;
195	
196	    if (edgeScrollAnimRef.current) {
197	      cancelAnimationFrame(edgeScrollAnimRef.current);
198	      edgeScrollAnimRef.current = null;
199	    }
200	
201	    if (distToRight >= 0 && distToRight < 60) {
202	      const speed = Math.max(2, Math.round((60 - distToRight) * 0.4));
203	      const step = () => {
204	        if (tableContainerRef.current) {
205	          tableContainerRef.current.scrollLeft += speed;
206	          checkScrollBoundaries();
207	        }
208	      };
209	      edgeScrollAnimRef.current = requestAnimationFrame(step);
210	    } else if (distToLeft >= 0 && distToLeft < 60) {
211	      const speed = Math.max(2, Math.round((60 - distToLeft) * 0.4));
212	      const step = () => {
213	        if (tableContainerRef.current) {
214	          tableContainerRef.current.scrollLeft -= speed;
215	          checkScrollBoundaries();
216	        }
217	      };
218	      edgeScrollAnimRef.current = requestAnimationFrame(step);
219	    }
220	  };
221	
222	  const handleMouseUpOrLeave = () => {
223	    isDraggingRef.current = false;
224	    if (edgeScrollAnimRef.current) {
225	      cancelAnimationFrame(edgeScrollAnimRef.current);
226	      edgeScrollAnimRef.current = null;
227	    }
228	    checkScrollBoundaries();
229	  };
230	
231	  // Shift+Wheel or Header Wheel horizontal scrolling
232	  const handleWheel = (e: React.WheelEvent<HTMLDivElement>) => {
233	    if (!tableContainerRef.current) return;
234	    if (e.shiftKey || Math.abs(e.deltaX) > 0) {
235	      tableContainerRef.current.scrollLeft += e.deltaX || e.deltaY;
236	      checkScrollBoundaries();
237	    }
238	  };
239	
240	  // Flat array of working entries
241	  const entriesList = useMemo(() => {
242	    return Object.entries(workingEntries).map(([key, entry]) => ({
243	      key,
244	      entry,
245	    }));
246	  }, [workingEntries]);
247	
248	  // Counts for status
249	  const completedCount = useMemo(() => entriesList.filter((e) => Boolean(e.entry.completed)).length, [entriesList]);
250	  const draftCount = useMemo(() => entriesList.filter((e) => !e.entry.completed).length, [entriesList]);
251	  const tagTeamCount = useMemo(() => entriesList.filter((e) => e.entry.tag_team && e.entry.tag_team.length > 0).length, [entriesList]);
252	
253	  // Filtered rows for search & filter
254	  const filteredEntries = useMemo(() => {
255	    return entriesList.filter(({ key, entry }) => {
256	      if (filterMode === 'completed' && !entry.completed) return false;
257	      if (filterMode === 'draft' && Boolean(entry.completed)) return false;
258	      if (filterMode === 'tag_team' && (!entry.tag_team || entry.tag_team.length === 0)) return false;
259	
260	      if (!searchQuery.trim()) return true;
261	      const q = searchQuery.toLowerCase();
262	      return (
263	        key.toLowerCase().includes(q) ||
264	        (entry.display_name && entry.display_name.toLowerCase().includes(q)) ||
265	        (entry.prompt && entry.prompt.toLowerCase().includes(q)) ||
266	        (entry.keywords && entry.keywords.some((k: string) => k.toLowerCase().includes(q))) ||
267	        (entry.requirement && entry.requirement.some((r: string) => r.toLowerCase().includes(q))) ||
268	        (entry.impact && entry.impact.some((i: string) => i.toLowerCase().includes(q)))
269	      );
270	    });
271	  }, [entriesList, searchQuery, filterMode]);
272	
273	  // All library options for Tag-Team picker dropdowns
274	  const allLibraryOptions = useMemo(() => {
275	    const list: { key: string; name: string; fileRelPath: string; prompt: string }[] = [];
276	    allFolderNodes.forEach((folder) => {
277	      folder.files.forEach((file) => {
278	        Object.entries(file.entries).forEach(([optKey, optEntry]) => {
279	          list.push({
280	            key: optKey,
281	            name: optEntry.display_name || optKey,
282	            fileRelPath: file.relPath,
283	            prompt: optEntry.prompt || '',
284	          });
285	        });
286	      });
287	    });
288	    return list;
289	  }, [allFolderNodes]);
290	
291	  // Helper to mark changes in the working copy
292	  const updateEntryField = useCallback((key: string, field: keyof ComponentEntry, value: any) => {
293	    setWorkingEntries((prev) => {
294	      const updated = {
295	        ...prev,
296	        [key]: {
297	          ...prev[key],
298	          [field]: value,
299	        },
300	      };
301	      return updated;
302	    });
303	    setIsDirty(true);
304	    setDirtyCount((prev) => prev + 1);
305	  }, []);
306	
307	  // Save changes to disk
308	  const handleSaveToDisk = useCallback(async () => {
309	    if (!app || !activeFileNode || isSaving) return;
310	    setIsSaving(true);
311	
312	    const success = await ComponentManager.saveAllFileEntries(
313	      app,
314	      activeFileNode.relPath,
315	      workingEntries
316	    );
317	
318	    if (success) {
319	      await reload();
320	      setIsDirty(false);
321	      setDirtyCount(0);
322	      setSaveSuccessNotice(true);
323	      setTimeout(() => setSaveSuccessNotice(false), 2000);
324	    } else {
325	      window.alert(`Failed to save changes to ${activeFileNode.relPath}`);
326	    }
327	    setIsSaving(false);
328	  }, [app, activeFileNode, workingEntries, isSaving, reload]);
329	
330	  // Discard in-memory edits
331	  const handleDiscardChanges = () => {
332	    if (!activeFileNode) return;
333	    if (window.confirm('Discard all unsaved edits for this file?')) {
334	      setWorkingEntries(JSON.parse(JSON.stringify(activeFileNode.entries || {})));
335	      setIsDirty(false);
336	      setDirtyCount(0);
337	    }
338	  };
339	
340	  // Keyboard shortcut: Ctrl+S / Cmd+S to save
341	  useEffect(() => {
342	    const handleKeyDown = (e: KeyboardEvent) => {
343	      if ((e.ctrlKey || e.metaKey) && e.key === 's') {
344	        e.preventDefault();
345	        if (isDirty) {
346	          handleSaveToDisk();
347	        }
348	      }
349	    };
350	    window.addEventListener('keydown', handleKeyDown);
351	    return () => window.removeEventListener('keydown', handleKeyDown);
352	  }, [isDirty, handleSaveToDisk]);
353	
354	  // Add a new row directly into the table
355	  const handleAddNewRow = () => {
356	    const newHex = generateHexId();
357	    const newOption: ComponentEntry = {
358	      display_name: 'New Option',
359	      prompt: '',
360	      keywords: [],
361	      require: [],
362	      exclude: [],
363	      requirement: [],
364	      impact: [],
365	      subjects: [0, 0],
366	    };
367	
368	    setWorkingEntries((prev) => ({
369	      ...prev,
370	      [newHex]: newOption,
371	    }));
372	    setIsDirty(true);
373	    setDirtyCount((prev) => prev + 1);
374	  };
375	
376	  // Duplicate a row
377	  const handleDuplicateRow = (key: string, entry: ComponentEntry) => {
378	    const newHex = generateHexId();
379	    const duplicated: ComponentEntry = {
380	      ...JSON.parse(JSON.stringify(entry)),
381	      display_name: `${entry.display_name || key} (Copy)`,
382	    };
383	
384	    setWorkingEntries((prev) => ({
385	      ...prev,
386	      [newHex]: duplicated,
387	    }));
388	    setIsDirty(true);
389	    setDirtyCount((prev) => prev + 1);
390	  };
391	
392	  // Delete a row
393	  const handleDeleteRow = (key: string) => {
394	    setWorkingEntries((prev) => {
395	      const updated = { ...prev };
396	      delete updated[key];
397	      return updated;
398	    });
399	    setIsDirty(true);
400	    setDirtyCount((prev) => prev + 1);
401	  };
402	
403	  // Inline Tag-Team toggle
404	  const handleToggleTagTeam = (key: string, currentTagTeam: string[] | undefined, targetKey: string) => {
405	    const list = Array.isArray(currentTagTeam) ? [...currentTagTeam] : [];
406	    const exists = list.includes(targetKey);
407	    const updated = exists ? list.filter((k) => k !== targetKey) : [...list, targetKey];
408	    updateEntryField(key, 'tag_team', updated);
409	  };
410	
411	  // Inline Tag Add for Requirements & Impacts
412	  const handleAddTag = (key: string, field: 'requirement' | 'impact', tagValue: string) => {
413	    const clean = tagValue.trim().toLowerCase();
