144	function expandInlineChoices(text: string): string {
145	  return text.replace(/\{([^{}]+)\}/g, (_, group) => {
146	    const choices = group.split('|').map((s: string) => s.trim()).filter(Boolean);
147	    if (choices.length === 0) return '';
148	    return choices[Math.floor(Math.random() * choices.length)] || '';
149	  });
150	}
