152	/**
153	 * Dynamically filters random pools for any matrix domain based on active base states & unlocked pools.
154	 */
155	function applyMatrixDomainFilters(
156	  matrixDomains: MatrixDomainNode[],
157	  currentRandomPools: Record<string, string[]>,
158	  matrixBaseStates: Record<string, string[]>,
159	  matrixUnlockedPools: Record<string, string[]>
160	): Record<string, string[]> {
161	  const updatedPools = { ...currentRandomPools };
162	
163	  for (const domain of matrixDomains) {
164	    const baseStates = matrixBaseStates[domain.domainId] || [];
165	    const unlockedPools = matrixUnlockedPools[domain.domainId] || [];
166	    const combinedActiveStates = Array.from(new Set([...baseStates, ...unlockedPools]));
167	
168	    for (const file of domain.files) {
169	      const allOptionKeys = Object.keys(file.entries);
170	      if (combinedActiveStates.length === 0) {
171	        // When no matrix states are selected, all options remain active
172	        updatedPools[file.relPath] = allOptionKeys;
173	      } else {
174	        // Filter options matching any of the active matrix states
175	        const matchingKeys = allOptionKeys.filter((key) => {
176	          const entry = file.entries[key];
177	          const entryTags = [
178	            ...(Array.isArray(entry.emotions) ? entry.emotions : []),
179	            ...(Array.isArray(entry.postures) ? entry.postures : []),
180	            ...(Array.isArray(entry.tags) ? entry.tags : []),
181	            ...(Array.isArray(entry.keywords) ? entry.keywords : []),
182	          ].map((t: string) => t.toLowerCase().trim());
183	
184	          return entryTags.some((tag: string) => combinedActiveStates.includes(tag));
185	        });
186	
187	        updatedPools[file.relPath] = matchingKeys.length > 0 ? matchingKeys : allOptionKeys;
188	      }
189	    }
190	  }
191	
192	  return updatedPools;
193	}
