471	      if (clean) activeConditionIds.add(clean);
472	    });
473	  });
474	
475	  // Expand tag_team on active conditions
476	  console.log('[ConditionEngine] Expanding tag_team from active conditions:', Array.from(activeConditionIds));
477	  Array.from(activeConditionIds).forEach((condId) => {
478	    const cond = conditions[condId];
